steps.script:
# The Attached unit gets ONE reinforcement row naming both units; the leader
# never gets a row of its own (it arrives with its bodyguard).
var texts = tree.current_scene.movement_controller.get_unit_list_texts()
var row = ""
for t in texts:
	if str(t).begins_with("Arrive from"):
		row += str(t) + "|"
return row

var list = tree.current_scene.movement_controller.unit_list
for i in range(list.item_count):
	if str(list.get_item_metadata(i)) == "U_CUSTODIAN_GUARD_B":
		return i
return -1

var dc = tree.current_scene.deployment_controller
var cm = dc.combined_models[dc.model_idx]
return str(cm["unit_id"])

# And it does not overlap any of the guards it arrived with.
var champ = GameState.get_unit("U_BLADE_CHAMPION_A").models[0]
var worst = 9999.0
for m in GameState.get_unit("U_CUSTODIAN_GUARD_B").models:
	if m.get("position", null) == null:
		continue
	if Measurement.models_overlap(champ, m):
		return "OVERLAP"
	worst = min(worst, Measurement.model_to_model_distance_px(champ, m))
return "CLEAR" if worst > 0.0 else "TOUCHING"

# The arrived unit must drop out of the reinforcements list. It used to
# linger (only the HIDDEN deployment list was refreshed), and clicking the
# stale row started a normal move on a unit that had just ingressed —
# "Error: Unit has already moved this phase".
var texts = tree.current_scene.movement_controller.get_unit_list_texts()
var rows = []
for t in texts:
	if str(t).begins_with("Arrive from"):
		rows.append(str(t))
return "|".join(rows)

# ...and it now appears under DEPLOYED UNITS as one Attached unit.
var texts = tree.current_scene.movement_controller.get_unit_list_texts()
for t in texts:
	if str(t).begins_with("Custodian Guard"):
		return str(t)
return "NOT_LISTED"
